-- Onconic : Key trials, une fiche par étude clé (lecture : membres validés ; rédaction : admins).
-- À exécuter une fois dans Supabase > SQL Editor > Run (peut être relancé sans risque).
-- Les fiches sont créées en brouillon : seules les fiches publiées sont visibles des membres.

create table if not exists public.key_trials (
  id bigint generated always as identity primary key,
  slug text not null unique check (slug ~ '^[a-z0-9-]{2,60}$'),
  acronym text not null,
  title text not null,
  status text not null default 'draft' check (status in ('draft', 'published')),
  clinic text,
  diagnosis text,
  markers text,
  lines text[] not null default '{}',
  drugs text,
  phase text,
  design jsonb not null default '{}',
  outcomes jsonb not null default '[]',
  km jsonb not null default '[]',
  seeded_at timestamptz,
  safety text,
  summary text,
  strengths text,
  limitations text,
  practice text check (practice in ('oui', 'partiel', 'non')),
  practice_text text,
  refs jsonb not null default '[]',
  reviewed_by text,
  reviewed_at date,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- Colonnes ajoutées après le premier lot : courbes de survie, date de la dernière mise à jour par ce script
alter table public.key_trials add column if not exists km jsonb not null default '[]';
alter table public.key_trials add column if not exists seeded_at timestamptz;
-- Tableau des effets indésirables principaux : { arms, grade, rows: [[effet, tous grades, grade ≥ 3, …]], source }
alter table public.key_trials add column if not exists ae jsonb not null default '{}';

alter table public.key_trials enable row level security;
drop policy if exists "key_trials: members read published" on public.key_trials;
create policy "key_trials: members read published" on public.key_trials for select to authenticated
  using ((status = 'published' and public.is_hive_member()) or public.current_role_name() = 'admin');
drop policy if exists "key_trials: admin write" on public.key_trials;
create policy "key_trials: admin write" on public.key_trials for all to authenticated
  using (public.current_role_name() = 'admin') with check (public.current_role_name() = 'admin');
revoke all on public.key_trials from anon;
grant select, insert, update, delete on public.key_trials to authenticated;

create or replace function public.key_trials_stamp()
returns trigger language plpgsql set search_path = public as $$
begin
  new.updated_at := now();
  return new;
end;
$$;
drop trigger if exists key_trials_stamp on public.key_trials;
create trigger key_trials_stamp before update on public.key_trials
  for each row execute function public.key_trials_stamp();

-- Ajout ou mise à jour d'une fiche de départ (exécuté depuis le SQL Editor). Une fiche existante n'est mise à jour
-- que si personne ne l'a modifiée depuis le dernier passage de ce script, ni marquée comme relue.
create or replace function public.trials_seed(p jsonb)
returns void language sql set search_path = public as $$
  insert into public.key_trials (slug, acronym, title, clinic, diagnosis, markers, lines, drugs, phase, design, outcomes,
    safety, summary, strengths, limitations, practice, practice_text, refs, km, ae, seeded_at)
  values (p ->> 'slug', p ->> 'acronym', p ->> 'title', p ->> 'clinic', p ->> 'diagnosis', nullif(p ->> 'markers', ''),
    array(select jsonb_array_elements_text(p -> 'lines')), p ->> 'drugs', p ->> 'phase', p -> 'design', p -> 'outcomes',
    p ->> 'safety', p ->> 'summary', p ->> 'strengths', p ->> 'limitations', p ->> 'practice', p ->> 'practice_text', p -> 'refs',
    coalesce(p -> 'km', '[]'), coalesce(p -> 'ae', '{}'), now())
  on conflict (slug) do update set title = excluded.title, diagnosis = excluded.diagnosis, markers = excluded.markers,
    lines = excluded.lines, drugs = excluded.drugs, phase = excluded.phase, design = excluded.design, outcomes = excluded.outcomes,
    km = excluded.km, ae = excluded.ae, safety = excluded.safety, summary = excluded.summary, strengths = excluded.strengths,
    limitations = excluded.limitations, practice = excluded.practice, practice_text = excluded.practice_text,
    refs = excluded.refs, seeded_at = now()
  where key_trials.reviewed_by is null
    and (key_trials.updated_at = key_trials.created_at or key_trials.updated_at = key_trials.seeded_at);
$$;
revoke execute on function public.trials_seed(jsonb) from public, anon, authenticated;

-- Rattrapage : les fiches mises à jour ensemble par une version précédente de ce script (même horodatage
-- pour au moins 5 fiches, jamais relues) sont considérées comme non modifiées à la main.
update public.key_trials k set seeded_at = now()
where k.seeded_at is null and k.reviewed_by is null
  and (select count(*) from public.key_trials x where x.updated_at = k.updated_at) >= 5;


